classdef APYV9WebApp < matlab.apps.AppBase

    % Properties that correspond to app components
    properties (Access = public)
        UIFigure                        matlab.ui.Figure
        MainTabGroup                    matlab.ui.container.TabGroup
        ScenarioTab                     matlab.ui.container.Tab
        LoadScenarioButton              matlab.ui.control.Button
        SaveScenarioButton              matlab.ui.control.Button
        UseDefaultsCheckBox             matlab.ui.control.CheckBox
        ScenarioLabelEditField          matlab.ui.control.EditField
        ScenarioLabel                   matlab.ui.control.Label
        InputsTab                       matlab.ui.container.Tab
        RegimenEffFullEditField         matlab.ui.control.NumericEditField
        RegimenEffFullEditFieldLabel    matlab.ui.control.Label
        RegimenADRstopEditField         matlab.ui.control.NumericEditField
        RegimenADRstopEditFieldLabel    matlab.ui.control.Label
        RegimenPCompleteEditField       matlab.ui.control.NumericEditField
        RegimenPCompleteEditFieldLabel  matlab.ui.control.Label
        PStartTPTEditField              matlab.ui.control.NumericEditField
        PStartTPTEditFieldLabel         matlab.ui.control.Label
        ScreenCoverageEditField         matlab.ui.control.NumericEditField
        ScreenCoverageEditFieldLabel    matlab.ui.control.Label
        ScreeningStrategyDropDown       matlab.ui.control.DropDown
        ScreeningStrategyDropDownLabel  matlab.ui.control.Label
        RegimenDropDown                 matlab.ui.control.DropDown
        RegimenDropDownLabel            matlab.ui.control.Label
        TestTypeDropDown                matlab.ui.control.DropDown
        TesttypeLabel                   matlab.ui.control.Label
        ActiveTBPrevalenceEditField     matlab.ui.control.NumericEditField
        ActiveTBprevalenceLabel         matlab.ui.control.Label
        LtbiPrevalenceEditField         matlab.ui.control.NumericEditField
        TBIprevalenceLabel              matlab.ui.control.Label
        AdvancedTab                     matlab.ui.container.Tab
        NRepsEditField                  matlab.ui.control.NumericEditField
        NRepsEditFieldLabel             matlab.ui.control.Label
        RunTab                          matlab.ui.container.Tab
        ValidationMessagesTextArea      matlab.ui.control.TextArea
        ValidationMessagesLabel         matlab.ui.control.Label
        ValidateButton                  matlab.ui.control.Button
        RunButton                       matlab.ui.control.Button
        ResultsTab                      matlab.ui.container.Tab
        TechnicalDetailsTextArea        matlab.ui.control.TextArea
        TechnicalDetailsLabel           matlab.ui.control.Label
        HeadlineResultsTable            matlab.ui.control.Table
        DownloadsTab                    matlab.ui.container.Tab
        DownloadsTable                  matlab.ui.control.Table
        ExportResultsButton             matlab.ui.control.Button
    end


    properties (Access = private)
        AppState % Description
    end


    methods (Access = private)
        function txt = localIssueText(app, issue)
            txt = '';
            if isstruct(issue)
                if isfield(issue, 'message') && ~isempty(issue.message)
                    txt = char(string(issue.message));
                elseif isfield(issue, 'text') && ~isempty(issue.text)
                    txt = char(string(issue.text));
                else
                    txt = strtrim(evalc('disp(issue)'));
                end
            else
                txt = char(string(issue));
            end
        end

        function InputValueChanged(app, event)
            uiState = app_collect_ui_state_v9(app, app.AppState.Schema);
            app.AppState.CurrentUIState = uiState;

            if isfield(app.AppState.CurrentConfig, 'useDefaults')
                app.AppState.CurrentConfig.useDefaults = logical(app.UseDefaultsCheckBox.Value);
            end

            [app.AppState, ~] = app_input_changed_v9(app.AppState, uiState);

            refreshValidationDisplay(app);
            refreshResultsDisplay(app);
        end
        function refreshValidationDisplay(app)
            displayModel = validation_report_to_display_v9(app.AppState.LastValidationReport);

            lines = {
                displayModel.summaryText
                sprintf('Valid: %d', displayModel.isValid)
                sprintf('Warnings present: %d', displayModel.hasWarnings)
                };

            if ~isempty(displayModel.errorRows)
                for i = 1:numel(displayModel.errorRows)
                    lines{end+1, 1} = ['ERROR: ' app.localIssueText(displayModel.errorRows(i))]; %#ok<AGROW>
                end
            end

            if ~isempty(displayModel.warningRows)
                for i = 1:numel(displayModel.warningRows)
                    lines{end+1, 1} = ['WARNING: ' app.localIssueText(displayModel.warningRows(i))]; %#ok<AGROW>
                end
            end

            if ~isempty(displayModel.infoRows)
                for i = 1:numel(displayModel.infoRows)
                    lines{end+1, 1} = ['INFO: ' app.localIssueText(displayModel.infoRows(i))]; %#ok<AGROW>
                end
            end

            app.ValidationMessagesTextArea.Value = lines;

        end

        function refreshResultsDisplay(app)
            isStale = isstruct(app.AppState) && isfield(app.AppState, 'ResultsAreStale') ...
                && logical(app.AppState.ResultsAreStale);
            if isStale
                app.ResultsTab.Title = 'Results (stale)';
            else
                app.ResultsTab.Title = 'Results';
            end

            if isempty(app.AppState) || isempty(app.AppState.LastBundle)
                app.setUITableData(app.HeadlineResultsTable, [], "No results available");
                if isStale
                    app.TechnicalDetailsTextArea.Value = { ...
                        'STALE RESULTS: Inputs have changed. Re-run the scenario before using these outputs.'; ...
                        'No technical details available.'};
                else
                    app.TechnicalDetailsTextArea.Value = {'No technical details available.'};
                end
                app.setUITableData(app.DownloadsTable, [], "No downloads available yet");
                return;
            end

            displayModel = results_bundle_to_display_v9(app.AppState.LastBundle);

            headlineTbl = [];
            if isstruct(displayModel) && isfield(displayModel, 'headline') ...
                    && isfield(displayModel.headline, 'available') && displayModel.headline.available

                if isfield(displayModel.headline, 'keyMetricsTable') && istable(displayModel.headline.keyMetricsTable)
                    headlineTbl = displayModel.headline.keyMetricsTable;
                elseif isfield(displayModel.headline, 'summaryTable') && istable(displayModel.headline.summaryTable)
                    headlineTbl = displayModel.headline.summaryTable;
                elseif isfield(displayModel.headline, 'keyMetricsRows') && ~isempty(displayModel.headline.keyMetricsRows)
                    try
                        headlineTbl = struct2table(displayModel.headline.keyMetricsRows, 'AsArray', true);
                    catch
                    end
                end
            end
            app.setUITableData(app.HeadlineResultsTable, headlineTbl, "No results available");

            technicalLines = {};
            if isStale
                technicalLines{end+1,1} = 'STALE RESULTS: Inputs have changed. Re-run the scenario before using these outputs.';
            end

            if isstruct(displayModel) && isfield(displayModel, 'technical') ...
                    && isfield(displayModel.technical, 'available') && displayModel.technical.available

                technicalLines{end+1,1} = 'Technical details available.';

                if isfield(displayModel, 'metadata') && isstruct(displayModel.metadata)
                    if isfield(displayModel.metadata, 'contractVersion')
                        technicalLines{end+1,1} = ['Contract version: ' char(string(displayModel.metadata.contractVersion))];
                    end
                end

                if isfield(displayModel.technical, 'interfaceConfig') && ~isempty(displayModel.technical.interfaceConfig)
                    technicalLines{end+1,1} = 'Interface config summary:';
                    technicalLines{end+1,1} = strtrim(evalc('disp(displayModel.technical.interfaceConfig)'));
                end
            end

            if isempty(technicalLines)
                technicalLines = {'No technical details available.'};
            end

            app.TechnicalDetailsTextArea.Value = technicalLines;

            downloadsTbl = [];
            if isstruct(displayModel) && isfield(displayModel, 'downloads') ...
                    && isstruct(displayModel.downloads) ...
                    && isfield(displayModel.downloads, 'available') ...
                    && displayModel.downloads.available

                rows = struct([]);

                if isfield(displayModel.downloads, 'summaryCsv') && ~isempty(displayModel.downloads.summaryCsv)
                    rows(end+1).FileType = "Summary CSV"; %#ok<AGROW>
                    rows(end).Path = string(displayModel.downloads.summaryCsv);
                end

                if isfield(displayModel.downloads, 'keyMetricsCsv') && ~isempty(displayModel.downloads.keyMetricsCsv)
                    rows(end+1).FileType = "Key metrics CSV"; %#ok<AGROW>
                    rows(end).Path = string(displayModel.downloads.keyMetricsCsv);
                end

                if isfield(displayModel.downloads, 'payload') && ~isempty(displayModel.downloads.payload)
                    try
                        payloadFields = fieldnames(displayModel.downloads.payload);
                        for k = 1:numel(payloadFields)
                            val = displayModel.downloads.payload.(payloadFields{k});
                            if ischar(val) || isstring(val)
                                rows(end+1).FileType = string(payloadFields{k}); %#ok<AGROW>
                                rows(end).Path = string(val);
                            end
                        end
                    catch
                    end
                end

                if ~isempty(rows)
                    downloadsTbl = struct2table(rows);
                end
            end

            app.setUITableData(app.DownloadsTable, downloadsTbl, "No downloads available yet");

        end


        function setUITableData(app, uiTable, tbl, placeholderText)

            if nargin < 4 || isempty(placeholderText)
                placeholderText = "No data available";
            end

            if istable(tbl) && ~isempty(tbl)
                uiTable.Data = tbl;
                try
                    uiTable.ColumnName = tbl.Properties.VariableNames;
                catch
                end
            else
                uiTable.Data = table(string(placeholderText), 'VariableNames', {'Status'});
                uiTable.ColumnName = {'Status'};
            end

        end
    end


    % Callbacks that handle component events
    methods (Access = private)

        % Code that executes after component creation
        function startupFcn(app)

            drawnow;
            app.UIFigure.WindowState = 'maximized';

            [app.AppState, ~, ~] = app_startup_v9();
            app = app_apply_ui_state_v9(app, app.AppState.CurrentUIState, app.AppState.Schema);

            if isfield(app.AppState.CurrentConfig, 'useDefaults')
                app.UseDefaultsCheckBox.Value = logical(app.AppState.CurrentConfig.useDefaults);
            end

            refreshValidationDisplay(app);
            refreshResultsDisplay(app);

        end

        % Button pushed function: RunButton
        function RunButtonPushed(app, event)

            uiState = app_collect_ui_state_v9(app, app.AppState.Schema);
            app.AppState.CurrentUIState = uiState;

            if isfield(app.AppState.CurrentConfig, 'useDefaults')
                app.AppState.CurrentConfig.useDefaults = logical(app.UseDefaultsCheckBox.Value);
            end

            [app.AppState, ~, runError] = app_run_v9(app.AppState, uiState);

            refreshValidationDisplay(app);

            if ~isempty(runError)
                app.TechnicalDetailsTextArea.Value = { ...
                    'Run failed.'; ...
                    runError};
                return;
            end

            refreshResultsDisplay(app);

        end

        % Button pushed function: ValidateButton
        function ValidateButtonPushed(app, event)

            uiState = app_collect_ui_state_v9(app, app.AppState.Schema);
            app.AppState.CurrentUIState = uiState;

            if isfield(app.AppState.CurrentConfig, 'useDefaults')
                app.AppState.CurrentConfig.useDefaults = logical(app.UseDefaultsCheckBox.Value);
            end

            [app.AppState, ~, validationError] = app_validate_v9(app.AppState, uiState);

            refreshValidationDisplay(app);

            if ~isempty(validationError)
                app.ValidationMessagesTextArea.Value = { ...
                    'Validation failed.'; ...
                    validationError};
            end

        end

        % Button pushed function: LoadScenarioButton
        function LoadScenarioButtonPushed(app, event)

            [fileName, filePath] = uigetfile('*.json', 'Load scenario');
            if isequal(fileName, 0) || isequal(filePath, 0)
                return;
            end

            fullName = fullfile(filePath, fileName);
            [app.AppState, ~, ~, ~] = app_load_scenario_v9(app.AppState, fullName);

            app = app_apply_ui_state_v9(app, app.AppState.CurrentUIState, app.AppState.Schema);

            if isfield(app.AppState.CurrentConfig, 'useDefaults')
                app.UseDefaultsCheckBox.Value = logical(app.AppState.CurrentConfig.useDefaults);
            end

            refreshValidationDisplay(app);
            refreshResultsDisplay(app);


        end

        % Button pushed function: SaveScenarioButton
        function SaveScenarioButtonPushed(app, event)

            uiState = app_collect_ui_state_v9(app, app.AppState.Schema);
            app.AppState.CurrentUIState = uiState;
            app.AppState.CurrentConfig = ui_state_to_config_v9(uiState, app.AppState.Schema, app.AppState.CurrentConfig);

            if isfield(app.AppState.CurrentConfig, 'useDefaults')
                app.AppState.CurrentConfig.useDefaults = logical(app.UseDefaultsCheckBox.Value);
            end

            defaultFile = 'scenario_v9.json';
            if isfield(app.AppState.CurrentConfig, 'scenarioLabel') && ~isempty(app.AppState.CurrentConfig.scenarioLabel)
                defaultFile = [regexprep(char(string(app.AppState.CurrentConfig.scenarioLabel)), '[^a-zA-Z0-9_-]', '_') '.json'];
            end

            [fileName, filePath] = uiputfile('*.json', 'Save scenario', defaultFile);
            if isequal(fileName, 0) || isequal(filePath, 0)
                return;
            end

            fullName = fullfile(filePath, fileName);
            [app.AppState, ~, errMsg] = app_save_scenario_v9(app.AppState, fullName);

            if ~isempty(errMsg)
                app.ValidationMessagesTextArea.Value = { ...
                    'Save failed.'; ...
                    errMsg};
                return;
            end

            refreshValidationDisplay(app);

        end

        % Button pushed function: ExportResultsButton
        function ExportResultsButtonPushed(app, event)
            answer = inputdlg('Export base name:', 'Export results', 1, {'tb_screening_v9'});
            if isempty(answer)
                return;
            end

            baseName = strtrim(answer{1});
            if isempty(baseName)
                baseName = 'tb_screening_v9';
            end

            [app.AppState, ~, errMsg] = app_export_v9(app.AppState, baseName);

            if ~isempty(errMsg)
                app.TechnicalDetailsTextArea.Value = { ...
                    'Export failed.'; ...
                    errMsg};
                return;
            end
            refreshResultsDisplay(app);
        end

        % Value changed function: LtbiPrevalenceEditField
        function LtbiPrevalenceEditFieldValueChanged(app, event)
             InputValueChanged(app, event);

        end

        % Value changed function: ActiveTBPrevalenceEditField
        function ActiveTBPrevalenceEditFieldValueChanged(app, event)
             InputValueChanged(app, event);

        end

        % Value changed function: TestTypeDropDown
        function TestTypeDropDownValueChanged(app, event)
             InputValueChanged(app, event);

        end

        % Value changed function: RegimenDropDown
        function RegimenRegimenDropDownValueChanged(app, event)
             InputValueChanged(app, event);

        end

        % Value changed function: ScreeningStrategyDropDown
        function ScreeningStrategyDropDownValueChanged(app, event)
             InputValueChanged(app, event);

        end

        % Value changed function: ScreenCoverageEditField
        function ScreenCoverageEditFieldValueChanged(app, event)
             InputValueChanged(app, event);

        end

        % Value changed function: PStartTPTEditField
        function PStartTPTEditFieldValueChanged(app, event)
             InputValueChanged(app, event);

        end

        % Value changed function: RegimenPCompleteEditField
        function RegimenPCompleteEditFieldValueChanged(app, event)
             InputValueChanged(app, event);
        end

        % Value changed function: RegimenADRstopEditField
        function RegimenADRstopEditFieldValueChanged(app, event)
             InputValueChanged(app, event);

        end

        % Value changed function: RegimenEffFullEditField
        function RegimenEffFullEditFieldValueChanged(app, event)
             InputValueChanged(app, event);

        end

        % Value changed function: NRepsEditField
        function NRepsEditFieldValueChanged(app, event)
             InputValueChanged(app, event);

        end

        % Value changed function: ScenarioLabelEditField
        function ScenarioLabelEditFieldValueChanged(app, event)
            InputValueChanged(app, event);

        end

        % Value changed function: UseDefaultsCheckBox
        function UseDefaultsCheckBoxValueChanged(app, event)
            InputValueChanged(app, event);

        end
    end

    % Component initialization
