            app.ValidationMessagesLabel.Text = 'Validation Messages';

            % Create ValidationMessagesTextArea
            app.ValidationMessagesTextArea = uitextarea(app.RunTab);
            app.ValidationMessagesTextArea.Position = [288 452 150 60];

            % Create ResultsTab
            app.ResultsTab = uitab(app.MainTabGroup);
            app.ResultsTab.Title = 'Results';

            % Create HeadlineResultsTable
            app.HeadlineResultsTable = uitable(app.ResultsTab);
            app.HeadlineResultsTable.ColumnName = {'Column 1'; 'Column 2'; 'Column 3'; 'Column 4'};
            app.HeadlineResultsTable.RowName = {};
            app.HeadlineResultsTable.Position = [1 147 606 549];

            % Create TechnicalDetailsLabel
            app.TechnicalDetailsLabel = uilabel(app.ResultsTab);
            app.TechnicalDetailsLabel.HorizontalAlignment = 'right';
            app.TechnicalDetailsLabel.Position = [44 243 95 22];
            app.TechnicalDetailsLabel.Text = 'Technical Details';

            % Create TechnicalDetailsTextArea
            app.TechnicalDetailsTextArea = uitextarea(app.ResultsTab);
            app.TechnicalDetailsTextArea.Position = [154 207 150 60];

            % Create DownloadsTab
            app.DownloadsTab = uitab(app.MainTabGroup);
            app.DownloadsTab.Title = 'Downloads';

            % Create ExportResultsButton
            app.ExportResultsButton = uibutton(app.DownloadsTab, 'push');
            app.ExportResultsButton.ButtonPushedFcn = createCallbackFcn(app, @ExportResultsButtonPushed, true);
            app.ExportResultsButton.Position = [55 598 100 22];
            app.ExportResultsButton.Text = 'Export Results';

            % Create DownloadsTable
            app.DownloadsTable = uitable(app.DownloadsTab);
            app.DownloadsTable.ColumnName = {'Column 1'; 'Column 2'; 'Column 3'; 'Column 4'};
            app.DownloadsTable.RowName = {};
            app.DownloadsTable.Position = [180 136 291 526];

            % Show the figure after all components are created
            app.UIFigure.Visible = 'on';
        end
    end

    % App creation and deletion
    methods (Access = public)

        % Construct app
        function app = APYV9WebApp

            % Create UIFigure and components
            createComponents(app)

            % Register the app with App Designer
            registerApp(app, app.UIFigure)

            % Execute the startup function
            runStartupFcn(app, @startupFcn)

            if nargout == 0
                clear app
            end
        end

        % Code that executes before app deletion
        function delete(app)

            % Delete UIFigure when app is deleted
            delete(app.UIFigure)
        end
    end
end
